package com.stefan.smartvoice;

import android.app.Activity;
import android.app.AlertDialog;
import android.content.Intent;
import android.net.Uri;
import android.os.Bundle;
import android.view.ViewGroup;
import android.widget.Button;
import android.widget.EditText;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.TextView;
import android.widget.Toast;
import org.json.JSONArray;
import org.json.JSONObject;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;

public final class MainActivity extends Activity {
    private static final int IMPORT_DICT=101, EXPORT_DICT=102;
    private android.content.SharedPreferences prefs;
    private String page="home";
    @Override protected void onCreate(Bundle state) { super.onCreate(state); prefs=getSharedPreferences("smart_voice_settings",MODE_PRIVATE); show(prefs.getBoolean("welcome_completed",false)?"home":"welcome"); }
    @Override public void onBackPressed() { if (!"home".equals(page)) show("home"); else super.onBackPressed(); }
    private void show(String next) { page=next; ScrollView scroll=new ScrollView(this); scroll.setFillViewport(true); LinearLayout root=new LinearLayout(this); root.setOrientation(LinearLayout.VERTICAL); int p=dp(22); root.setPadding(p,dp(20),p,dp(28)); scroll.addView(root); setContentView(scroll); if("welcome".equals(next)) welcome(root); else if("dictionary".equals(next)) dictionary(root); else if("settings".equals(next)) settings(root); else home(root); }
    private void welcome(LinearLayout root) { heading(root,"Smart Voice"); label(root,tr("version")+" 0.0.1 · "+tr("developer")+" Stefan",16); label(root,tr("welcome"),18); label(root,tr("none"),16); button(root,tr("done"),()->{prefs.edit().putBoolean("welcome_completed",true).apply();show("home");}); }
    private void home(LinearLayout root) { heading(root,"Smart Voice"); label(root,tr("none_state"),18); button(root,tr("dictionary"),()->show("dictionary")); button(root,tr("settings"),()->show("settings")); }
    private void settings(LinearLayout root) { heading(root,tr("settings")); button(root,tr("language"),()->new AlertDialog.Builder(this).setTitle(tr("language")).setItems(new String[]{"English","Português","Español"},(d,n)->{prefs.edit().putString("ui_language",new String[]{"en","pt","es"}[n]).apply();show(page);}).show()); button(root,tr("contact"),()->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://t.me/damomgamer")));}catch(Exception e){toast(e);}}); button(root,tr("back"),()->show("home")); }
    private void dictionary(LinearLayout root) { heading(root,tr("dictionary")); button(root,tr("add"),()->edit(-1,"","")); JSONArray items=read(); if(items.length()==0)label(root,tr("empty"),16); for(int i=0;i<items.length();i++){JSONObject item=items.optJSONObject(i);if(item==null)continue;int n=i;String w=item.optString("word"),pron=item.optString("pronunciation");button(root,w+(pron.isEmpty()?"":" → "+pron),()->new AlertDialog.Builder(this).setTitle(w).setItems(new String[]{tr("edit"),tr("delete")},(d,c)->{if(c==0)edit(n,w,pron);else remove(n);}).show());} button(root,tr("import"),()->pick(IMPORT_DICT)); button(root,tr("export"),()->pick(EXPORT_DICT)); button(root,tr("clear"),()->new AlertDialog.Builder(this).setMessage(tr("clear_confirm")).setNegativeButton(tr("cancel"),null).setPositiveButton(tr("delete"),(d,w)->{save(new JSONArray());show("dictionary");}).show()); button(root,tr("back"),()->show("home")); }
    private void edit(int index,String word,String pronunciation) { LinearLayout fields=new LinearLayout(this);fields.setOrientation(LinearLayout.VERTICAL);EditText w=new EditText(this);w.setHint(tr("word"));w.setText(word);fields.addView(w,params());EditText pr=new EditText(this);pr.setHint(tr("pronunciation"));pr.setText(pronunciation);fields.addView(pr,params());new AlertDialog.Builder(this).setTitle(tr("dictionary")).setView(fields).setNegativeButton(tr("cancel"),null).setPositiveButton(tr("save"),(d,n)->{String text=w.getText().toString().trim();if(text.isEmpty())return;JSONArray a=read();JSONObject o=new JSONObject();try{o.put("word",text);o.put("pronunciation",pr.getText().toString().trim());if(index>=0&&index<a.length())a.put(index,o);else a.put(o);save(a);show("dictionary");}catch(Exception e){toast(e);}}).show(); }
    private void remove(int index){JSONArray a=read(),b=new JSONArray();for(int i=0;i<a.length();i++)if(i!=index)b.put(a.opt(i));save(b);show("dictionary");}
    private void pick(int request){Intent i=new Intent(request==EXPORT_DICT?Intent.ACTION_CREATE_DOCUMENT:Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(request==EXPORT_DICT?"text/plain":"*/*");if(request==IMPORT_DICT)i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"text/plain","application/octet-stream"});else i.putExtra(Intent.EXTRA_TITLE,"smart-voice-dictionary.txt");startActivityForResult(i,request);}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();try{if(request==IMPORT_DICT)importDict(uri);else if(request==EXPORT_DICT)exportDict(uri);}catch(Exception e){toast(e);}}
    private void importDict(Uri uri)throws Exception{JSONArray a=read();try(BufferedReader r=new BufferedReader(new InputStreamReader(getContentResolver().openInputStream(uri),StandardCharsets.UTF_8))){String line;while((line=r.readLine())!=null){String t=line.trim();if(t.isEmpty()||t.startsWith("#")||t.startsWith(";"))continue;int s=line.indexOf('=');if(s<1)s=line.indexOf('\t');if(s<1)s=line.indexOf(':');if(s<1)continue;JSONObject o=new JSONObject();o.put("word",line.substring(0,s).trim());o.put("pronunciation",line.substring(s+1).trim());a.put(o);}}save(a);show("dictionary");}
    private void exportDict(Uri uri)throws Exception{try(OutputStream out=getContentResolver().openOutputStream(uri)){JSONArray a=read();StringBuilder text=new StringBuilder();for(int n=0;n<a.length();n++){JSONObject o=a.optJSONObject(n);if(o!=null)text.append(o.optString("word")).append('=').append(o.optString("pronunciation")).append('\n');}out.write(text.toString().getBytes(StandardCharsets.UTF_8));}}
    private JSONArray read(){try{return new JSONArray(prefs.getString("dictionary","[]"));}catch(Exception e){return new JSONArray();}} private void save(JSONArray a){prefs.edit().putString("dictionary",a.toString()).apply();}
    private String tr(String k){String l=prefs==null?"en":prefs.getString("ui_language","en");String[][] t={{"welcome","Smart Voice is an accessible Android speech app. This clean source build contains no speech engine yet.","O Smart Voice é um aplicativo Android de fala acessível. Esta versão limpa do código ainda não contém um motor de síntese.","Smart Voice es una aplicación Android de voz accesible. Esta versión limpia aún no incluye motor de voz."},{"none","No speech engines, native engine libraries, or voice packages are included.","Nenhum motor, biblioteca nativa de síntese ou pacote de voz está incluído.","No se incluyen motores, bibliotecas nativas ni paquetes de voz."},{"none_state","Speech is unavailable until a speech engine is integrated. Voice import, downloads, selection, and playback are disabled.","A síntese ficará indisponível até a integração de um motor. Importação, downloads, seleção e reprodução de vozes estão desativados.","La síntesis no estará disponible hasta integrar un motor. La importación, descarga, selección y reproducción están desactivadas."},{"version","Version","Versão","Versión"},{"developer","Developer","Desenvolvedor","Desarrollador"},{"done","Done","Concluído","Hecho"},{"dictionary","User dictionary","Dicionário do usuário","Diccionario del usuario"},{"settings","Settings","Configurações","Configuración"},{"language","Interface language","Idioma da interface","Idioma de la interfaz"},{"contact","Contact the developer","Entrar em contato com o desenvolvedor","Contactar al desarrollador"},{"add","Add word","Adicionar palavra","Añadir palabra"},{"empty","The dictionary is empty.","O dicionário está vazio.","El diccionario está vacío."},{"edit","Edit","Editar","Editar"},{"delete","Delete","Excluir","Eliminar"},{"import","Import dictionary (TXT/CFG)","Importar dicionário (TXT/CFG)","Importar diccionario (TXT/CFG)"},{"export","Export dictionary","Exportar dicionário","Exportar diccionario"},{"clear","Delete dictionary","Apagar dicionário","Borrar diccionario"},{"clear_confirm","Delete every dictionary entry?","Apagar todas as palavras?","¿Borrar todas las palabras?"},{"word","Word","Palavra","Palabra"},{"pronunciation","Pronunciation","Pronúncia","Pronunciación"},{"save","Save","Salvar","Guardar"},{"cancel","Cancel","Cancelar","Cancelar"},{"back","Back","Voltar","Volver"}};for(String[] row:t)if(row[0].equals(k))return row["pt".equals(l)?2:"es".equals(l)?3:1];return k;}
    private TextView heading(LinearLayout p,String t){TextView v=label(p,t,28);v.setPadding(0,0,0,dp(16));return v;} private TextView label(LinearLayout p,String t,int size){TextView v=new TextView(this);v.setText(t);v.setTextSize(size);v.setPadding(0,dp(8),0,dp(8));p.addView(v,params());return v;} private void button(LinearLayout p,String t,Runnable r){Button b=new Button(this);b.setText(t);b.setOnClickListener(v->r.run());p.addView(b,params());} private LinearLayout.LayoutParams params(){return new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);} private int dp(int n){return(int)(n*getResources().getDisplayMetrics().density+0.5f);} private void toast(Exception e){Toast.makeText(this,e.getMessage()==null?e.getClass().getSimpleName():e.getMessage(),Toast.LENGTH_LONG).show();}
}
